23	// registryCandidates returns all URL variants to look up in the engine's auth
24	// file.
25	func registryCandidates(registryURL string) []string {
26		base := strings.TrimSuffix(registryURL, "/")
27	
28		// Check if this URL is any known Docker Hub alias; if so, return the full set.
29		for _, alias := range dockerHubKeys {
30			if strings.EqualFold(base, strings.TrimSuffix(alias, "/")) {
31				return dockerHubKeys
32			}
33		}
34	
35		// Generic: bare hostname, https://, http:// variants.
36		candidates := []string{base}
37		if strings.HasPrefix(base, "https://") {
38			candidates = append(candidates, strings.TrimPrefix(base, "https://"))
39		} else if strings.HasPrefix(base, "http://") {
40			candidates = append(candidates, strings.TrimPrefix(base, "http://"))
41		} else {
42			candidates = append(candidates, "https://"+base, "http://"+base)
43		}
44		return candidates
45	}
