139	// RegistryLoginState reports whether credentials are stored for registryURL,
140	// and whether their secret is inline in the auth file or held by a helper.
141	//
142	// What `login` writes, measured on 2026-09-25 (docker 29.7.2, podman 5.7.0):
143	//
144	//	                 docker                     podman
145	//	no helper        auths[host] = {"auth":…}   auths[host] = {"auth":…}
146	//	credsStore       auths[host] = {}           ignored — written inline
147	//	credHelpers      auths[host] = {}           no auths entry at all
148	//
149	// Any inline secret wins, even next to a helper: a login made before the
150	// helper was configured leaves its base64 behind, and docker then ignores it
151	// without removing it — it is still on disk. Only the podman credHelpers case
152	// needs the helper itself asked, since the file keeps no trace of the login.
153	func RegistryLoginState(registryURL string) LoginState {
154		var cfg authFile
155		if err := readAuthFile(&cfg); err != nil {
156			return LoginNone
157		}
158		found := false
159		for _, c := range registryCandidates(registryURL) {
160			entry, ok := cfg.Auths[c]
161			if !ok {
162				continue
163			}
164			if entry.inline() {
165				return LoginInline
166			}
167			found = true
168		}
169		host := helperHost(registryURL)
170		if found {
171			// An empty entry holds nothing by itself: the secret is in the helper,
172			// and with no helper configured there is no secret anywhere.
173			if cfg.CredHelpers[host] != "" || cfg.CredsStore != "" {
174				return LoginHelper
175			}
176			return LoginNone
177		}
178		if helper := cfg.CredHelpers[host]; helper != "" {
179			if _, _, ok := getCredsFromHelper(helper, host); ok {
180				return LoginHelper
181			}
182		}
183		return LoginNone
184	}
