213	// section of the engine's credential file. Errors are non-fatal (best effort).
214	func removeFromAuthFile(registryURL string) error {
215		configPath, err := authPath()
216		if err != nil {
217			return err
218		}
219	
220		var raw map[string]json.RawMessage
221		if err := readAuthFile(&raw); err != nil {
222			return err
223		}
224		authsRaw, ok := raw["auths"]
225		if !ok {
226			return nil
227		}
228		var auths map[string]json.RawMessage
229		if err := json.Unmarshal(authsRaw, &auths); err != nil {
230			return err
231		}
232	
233		changed := false
234		for _, candidate := range registryCandidates(registryURL) {
235			if _, exists := auths[candidate]; exists {
236				delete(auths, candidate)
237				changed = true
238			}
239		}
240		if !changed {
241			return nil
242		}
243	
244		updated, err := json.Marshal(auths)
245		if err != nil {
246			return err
247		}
248		raw["auths"] = updated
249		out, err := json.MarshalIndent(raw, "", "\t")
250		if err != nil {
251			return err
252		}
253		return os.WriteFile(configPath, out, 0600)
254	}
