256	// GetStoredCreds retrieves registry credentials for registryURL from the
257	// engine's auth file. It tries the per-registry credential helper
258	// (credHelpers), then the global credsStore, and finally falls back to the
259	// inline base64-encoded auth field. Returns ok=false when no credentials are
260	// found.
261	func GetStoredCreds(registryURL string) (username, password string, ok bool) {
262		var cfg authFile
263		if err := readAuthFile(&cfg); err != nil {
264			return "", "", false
265		}
266	
267		hostname := helperHost(registryURL)
268	
269		helper := cfg.CredHelpers[hostname]
270		if helper == "" {
271			helper = cfg.CredsStore
272		}
273		if helper != "" {
274			if u, p, ok := getCredsFromHelper(helper, hostname); ok {
275				return u, p, true
276			}
277		}
278	
279		for _, candidate := range registryCandidates(registryURL) {
280			if entry, ok := cfg.Auths[candidate]; ok && entry.Auth != "" {
281				if u, p, ok := decodeAuth(entry.Auth); ok {
282					return u, p, true
283				}
284			}
285		}
286		return "", "", false
287	}
288	
289	// decodeAuth splits a base64 "username:password" auth field.
290	func decodeAuth(auth string) (username, password string, ok bool) {
291		decoded, err := base64.StdEncoding.DecodeString(auth)
292		if err != nil {
293			return "", "", false
294		}
295		if idx := strings.IndexByte(string(decoded), ':'); idx >= 0 {
296			return string(decoded[:idx]), string(decoded[idx+1:]), true
297		}
298		return "", "", false
299	}
