301	// getCredsFromHelper calls `docker-credential-<helper> get` and parses the JSON response.
302	func getCredsFromHelper(helper, serverURL string) (username, password string, ok bool) {
303		out, err := runner.Run(dockerCmd{
304			Args:   []string{"get"},
305			Stdin:  serverURL,
306			Helper: helper,
307		})
308		if err != nil {
309			return "", "", false
310		}
311		var result struct {
312			Username string `json:"Username"`
313			Secret   string `json:"Secret"`
314		}
315		if err := json.Unmarshal(out, &result); err != nil {
316			return "", "", false
317		}
318		if result.Secret == "" {
319			return "", "", false
320		}
321		return result.Username, result.Secret, true
322	}
