13	// dockerHubKeys lists all keys Docker uses for Docker Hub in ~/.docker/config.json.
14	// `docker login docker.io` stores credentials under "https://index.docker.io/v1/".
15	var dockerHubKeys = []string{
16		"docker.io",
17		"registry-1.docker.io",
18		"https://index.docker.io/v1/",
19		"https://index.docker.io/v1",
20		"https://registry-1.docker.io",
21	}
