74	// readAuthFile reads and unmarshals the engine's credential file into v.
75	func readAuthFile(v any) error {
76		path, err := authPath()
77		if err != nil {
78			return err
79		}
80		data, err := os.ReadFile(path)
81		if err != nil {
82			return err
83		}
84		return json.Unmarshal(data, v)
85	}
