87	// RegistryLogin authenticates with a Docker/OCI registry using `docker login`.
88	// The password is passed via stdin to avoid exposing it in the process list.
89	func RegistryLogin(registryURL, username, password string) error {
90		if err := requireEngine(); err != nil {
91			return err
92		}
93		output, err := runner.Run(dockerCmd{
94			Args:     []string{"login", registryURL, "-u", username, "--password-stdin"},
95			Stdin:    password,
96			Combined: true,
97		})
98		if err != nil {
99			return errWithOutput(cmdLabel("login"), output)
100		}
101		return nil
102	}
