186	// helperHost normalises a registry URL to the bare hostname credential
187	// helpers are keyed on.
188	func helperHost(registryURL string) string {
189		host := strings.TrimSuffix(registryURL, "/")
190		for _, prefix := range []string{"https://", "http://"} {
191			host = strings.TrimPrefix(host, prefix)
192		}
193		return host
194	}
