196	// RegistryLogout removes stored credentials for an OCI registry.
197	// It runs `<engine> logout` (cleans system credential stores) then directly
198	// removes all matching keys from the engine's auth file to handle cases where
199	// logout leaves behind alias entries (e.g. docker.io vs https://index.docker.io/v1/).
200	func RegistryLogout(registryURL string) error {
201		if err := requireEngine(); err != nil {
202			return err
203		}
204		if err := mutate(cmdLabel("logout"), "logout", registryURL); err != nil {
205			return err
206		}
207		// Also remove all matching alias keys directly from config.json.
208		_ = removeFromAuthFile(registryURL)
209		return nil
210	}
