212	// removeFromAuthFile removes all URL variants of registryURL from the auths
213	// section of the engine's credential file. Errors are non-fatal (best effort).
214	func removeFromAuthFile(registryURL string) error {
215		configPath, err := authPath()
216		if err != nil {
217			return err
218		}
219	
220		var raw map[string]json.RawMessage
221		if err := readAuthFile(&raw); err != nil {
222			return err
223		}
224		authsRaw, ok := raw["auths"]
225		if !ok {
226			return nil
227		}
228		var auths map[string]json.RawMessage
229		if err := json.Unmarshal(authsRaw, &auths); err != nil {
230			return err
231		}
232	
