147		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s", host, repoName)
148		body, err := n.nexusGET(ctx, endpoint, info)
149		if err != nil {
150			log.Printf("INFO [registrymgr/nexus] meta unreachable %q: %v", endpoint, err)
151			return "", "", nil, fmt.Errorf("reading %s: %w", endpoint, err)
152		}
153		if len(bytes.TrimSpace(body)) == 0 {
154			log.Printf("INFO [registrymgr/nexus] meta %q: empty reply", repoName)
155			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errEmptyReply)
156		}
157		var result struct {
158			Type   string `json:"type"`
159			Format string `json:"format"`
160			Group  struct {
161				MemberNames []string `json:"memberNames"`
162			} `json:"group"`
163			Attributes struct {
164				Group struct {
165					MemberNames []string `json:"memberNames"`
166				} `json:"group"`
167			} `json:"attributes"`
168		}
