233	// membersFailure logs and types the failure of the first attempt on the format
234	// endpoint: a refusal when the manager refused the account, the error itself
235	// otherwise. The returned error holds the group and the status, never the URL.
236	func membersFailure(host, repoName, endpoint string, err error, hasAuth bool) error {
