259	// parseGroupMembers reads the member names of a format-endpoint reply. A document
260	// is a `group` object carrying a `memberNames` key, an empty list included: an
261	// empty body, `null`, `{}` or a group without the key is not one, and reading it
262	// as "no members" would be cached over what was last known.
263	func parseGroupMembers(body []byte) ([]string, error) {
264		if len(bytes.TrimSpace(body)) == 0 {
265			return nil, errEmptyReply
266		}
267		var doc struct {
268			Group *struct {
269				MemberNames []string `json:"memberNames"`
270			} `json:"group"`
271		}
272		if err := json.Unmarshal(body, &doc); err != nil {
273			return nil, fmt.Errorf("parsing the reply: %w", err)
