281	// refusedStatus reports the status of a management API refusal: 401 or 403 from
282	// the manager itself, not from anything in front of it, or the 404 Nexus answers
283	// an account without nx-repository-admin (see repositoryNotFoundError).
284	func refusedStatus(err error) (int, bool) {
285		var nf *repositoryNotFoundError
286		if errors.As(err, &nf) {
287			return http.StatusNotFound, true
288		}
289		var se *oci.StatusError
290		if !errors.As(err, &se) || se.Source != oci.SourceManagementAPI {
291			return 0, false
292		}
293		if se.Code != http.StatusUnauthorized && se.Code != http.StatusForbidden {
294			return 0, false
295		}
296		return se.Code, true
297	}
