299	// memberList turns the names a group declares into addresses.
300	func memberList(dockerURL string, names []string) []GroupMember {
301		members := make([]GroupMember, 0, len(names))
302		for _, name := range names {
303			url, prefix := memberAddress(dockerURL, name)
304			members = append(members, GroupMember{
