313	// memberAddress decides how one member of a group is reached, from the URL the
314	// group itself is pulled from.
315	//
316	// A group written as a path prefix — `host/repository/<group>` — is an instance
317	// serving its Docker repositories that way, so its members are reached the same
318	// way: the host, with the member's name in front of the repository. That pair is
319	// consistent by construction, because browse and pull build the same path from
320	// it.
321	//
322	// Anything else is a connector of the group's own — a dedicated port, a
323	// subdomain — and says nothing about a member. Which of those a repository
324	// answers on is a setting on that repository (`docker.httpPort`,
325	// `docker.httpsPort`, `docker.subdomain`), and the endpoint carrying it is
326	// refused to an ordinary pull account. So nothing is claimed: the member is
327	// offered at the group's own address with no prefix, which browses to nothing
328	// visibly rather than pulling to nothing plausibly (§3.18).
329	func memberAddress(dockerURL, memberName string) (url, prefix string) {
330		host, _, err := parseNexusURL(dockerURL)
331		if err != nil {
332			return dockerURL, ""
333		}
334		// parseNexusURL supplies https:// for a URL written without a scheme. The
335		// group's own spelling is what the rest of the application is keyed on, so
336		// it is kept rather than normalised here.
337		if !strings.Contains(strings.ToLower(dockerURL), "://") {
338			host = strings.TrimPrefix(host, "https://")
339		}
340		return host, memberName
341	}
