343	// nexusGET performs an authenticated GET and returns the response body. A status
344	// other than 200 is a *oci.StatusError from the management API: the code only, no
345	// status line, body or header. A 404 whose body is Nexus's own "Repository not
346	// found" is a *repositoryNotFoundError, which wraps that same status error. A
347	// context error stays a context error.
348	func (n *NexusDetector) nexusGET(ctx context.Context, endpoint string, info RegistryInfo) ([]byte, error) {
349		req, err := http.NewRequestWithContext(ctx, "GET", endpoint, nil)
350		if err != nil {
351			return nil, err
352		}
353		if info.Username != "" && info.Password != "" {
354			req.SetBasicAuth(info.Username, info.Password)
355		}
356		resp, err := nexusHTTPClient.Do(req)
357		if err != nil {
358			// A refused redirect comes back without the URL it pointed to, which
359			// may be signed.
360			return nil, oci.StripRedirectTarget(err)
361		}
362		defer func() { _ = resp.Body.Close() }()
363		if resp.StatusCode != http.StatusOK {
364			status := &oci.StatusError{Code: resp.StatusCode, Source: oci.SourceManagementAPI}
365			if resp.StatusCode != http.StatusNotFound {
366				return nil, status
367			}
368			errBody, err := oci.ReadAllLimited(resp.Body, maxNexusErrorBody)
369			if err != nil {
370				if ctxErr := ctx.Err(); ctxErr != nil {
371					return nil, fmt.Errorf("read Nexus response: %w", ctxErr)
372				}
373				return nil, status
374			}
375			if isRepositoryNotFound(errBody) {
376				return nil, &repositoryNotFoundError{status: status}
377			}
378			return nil, status
379		}
380		body, err := oci.ReadAllLimited(resp.Body, maxNexusResponse)
381		if err != nil {
382			// Which error net/http gives a body cut by a cancel varies: report the
383			// context's own.
384			if ctxErr := ctx.Err(); ctxErr != nil {
385				return nil, fmt.Errorf("read Nexus response: %w", ctxErr)
386			}
387			return nil, fmt.Errorf("read Nexus response: %w", err)
388		}
389		return body, nil
390	}
