392	// parseNexusURL extracts the scheme+host and repository name from a Nexus URL.
393	// e.g. "https://nexus.example.com/repository/docker-group" → ("https://nexus.example.com", "docker-group")
394	func parseNexusURL(registryURL string) (host, repoName string, err error) {
395		raw := registryURL
396		if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
397			raw = "https://" + raw
398		}
399		u, err := url.Parse(raw)
400		if err != nil {
401			return "", "", err
402		}
403		parts := strings.SplitN(strings.TrimPrefix(u.Path, "/"), "/", 3)
404		// Expected: ["repository", "<repoName>", ...]
405		if len(parts) < 2 || parts[0] != "repository" || parts[1] == "" {
406			return "", "", fmt.Errorf("not a Nexus repository path: %q", u.Path)
407		}
408		host = u.Scheme + "://" + u.Host
409		repoName = parts[1]
410		return host, repoName, nil
411	}
