413	// cleanMemberAlias strips common suffixes (-proxy, -hosted, -local) for a friendlier display name.
414	func cleanMemberAlias(name string) string {
415		for _, suffix := range []string{"-proxy", "-hosted", "-local"} {
416			if strings.HasSuffix(name, suffix) {
417				return name[:len(name)-len(suffix)]
418			}
419		}
420		return name
421	}
